"""R3 long monthly history, stable colors, bounded SVG and Live ranking migration."""
import json,threading,statistics
from datetime import datetime,timezone
from http.server import ThreadingHTTPServer
from playwright.sync_api import sync_playwright,expect
from insights_polish import E,SEED,SNAP,order
from ui_v0322 import QuietHandler,KEY

def main():
 server=ThreadingHTTPServer(('127.0.0.1',0),QuietHandler);threading.Thread(target=server.serve_forever,daemon=True).start();base=f'http://127.0.0.1:{server.server_port}';results=[]
 with sync_playwright() as pw:
  browser=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
  for years,width in [(n,390) for n in [24,30,40,55]]+[(55,w) for w in [320,375,393,430]]:
   ctx=browser.new_context(viewport=dict(width=width,height=844),is_mobile=True,has_touch=True);ctx.route('https://**/*',lambda r:r.abort());p=ctx.new_page();p.clock.set_fixed_time(datetime(2026,11,27,tzinfo=timezone.utc));p.goto(base);p.evaluate('MLAReady');p.locator('[data-section=live]').click();p.locator('#insights-screen').click()
   data=p.evaluate('''async years=>{const first=2027-years,start=first*12,count=years*12-1,records=[];for(let i=0;i<count;i++){const n=i===0?1:i%5===0?0:i%7+1;for(let j=0;j<n;j++)records.push({date:Math.floor((start+i)/12)+'-'+String((start+i)%12+1).padStart(2,'0')})}const a=performance.now();MLAInsights.render(document.querySelector('#live-insights'),records,'live',false,new Date(2026,10,27));const renderCallMs=performance.now()-a;await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);return {months:count,records:records.length,renderCallMs,initialFrameMs:performance.now()-a}}''',years)
   viewport=p.locator('.insight-month-viewport');expect(viewport.locator('.insight-column').first).to_be_attached();assert viewport.evaluate('(e)=>Math.abs(e.scrollWidth-e.clientWidth-e.scrollLeft)<2');assert viewport.locator('.insight-column').count()<=18;assert p.locator('.insight-month-range').inner_text()=='2025-12–2026-11'
   axis=p.locator('.insight-month-axis');axis_x=axis.bounding_box()['x'];axis_text=axis.text_content();assert p.evaluate('document.documentElement.scrollWidth<=innerWidth')
   if width==390:p.locator('[data-insight=time]').screenshot(path=str(E/f'live-months-{years}-latest.png'))
   jump=p.locator('.insight-month-controls select');firstyear=str(2027-years);jump.select_option(firstyear);expect(p.locator('.insight-month-range')).to_contain_text(firstyear+'-01');assert viewport.evaluate('(e)=>e.scrollLeft')<2
   assert axis.bounding_box()['x']==axis_x;assert axis.text_content()==axis_text
   middle=str(2027-years//2);jump.select_option(middle);expect(p.locator('.insight-month-range')).to_contain_text(middle+'-01')
   jan=viewport.locator('[data-period="'+middle+'-01"]');expect(jan).to_be_attached();assert abs(jan.bounding_box()['x']-viewport.bounding_box()['x'])<12
   color=jan.get_attribute('fill');p.set_viewport_size(dict(width=320,height=844));expect(p.locator('.insight-month-range')).to_contain_text(middle+'-01');p.set_viewport_size(dict(width=width,height=844));viewport.focus();p.keyboard.press('Home');p.keyboard.press('End');jump.select_option(middle);expect(jan).to_be_attached();assert jan.get_attribute('fill')==color
   if width==390:p.locator('[data-insight=time]').screenshot(path=str(E/f'live-months-{years}-jump.png'))
   samples=p.evaluate('''async()=>{const e=document.querySelector('.insight-month-viewport'),samples=[];let maxBars=0;for(let i=0;i<20;i++){const a=performance.now();e.scrollLeft=(e.scrollWidth-e.clientWidth)*i/19;await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);samples.push(performance.now()-a);maxBars=Math.max(maxBars,e.querySelectorAll('.insight-column').length)}return {samples,maxBars}}''');assert samples['maxBars']<=18;data.update(years=years,width=width,maxRenderedBars=samples['maxBars'],scrollTwoFramesMedianMs=statistics.median(samples['samples']),scrollTwoFramesMaxMs=max(samples['samples']));results.append(data)
   assert axis.text_content()==axis_text;assert p.evaluate('document.documentElement.scrollWidth<=innerWidth');errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.evaluate('async()=>{const e=document.querySelector("#live-insights");e.hidden=true;await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);e.hidden=false;await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame)}');expect(p.locator('.insight-month-window')).to_be_attached();assert not errors,errors;print('PASS history',json.dumps(data),flush=True);ctx.close()
  # Old saved Live configuration is retained and the new ranking is appended, without rewriting records.
  ctx=browser.new_context(viewport=dict(width=390,height=844));ctx.route('https://**/*',lambda r:r.abort());old=dict(version=1,items=[dict(id='time',visible=True),dict(id='venue',visible=False),dict(id='artists',visible=True)])
  ctx.add_init_script('localStorage.setItem('+json.dumps(KEY)+','+json.dumps(json.dumps(SEED))+');if(!localStorage.getItem("mla-insights-layout-v1:live"))localStorage.setItem("mla-insights-layout-v1:live",'+json.dumps(json.dumps(old))+');localStorage.setItem("mma-ui-language","en")')
  p=ctx.new_page();p.goto(base);p.evaluate('MLAReady');p.locator('[data-section=live]').click();p.locator('#insights-screen').click();root=p.locator('#live-insights');assert order(root)==['time','artists','score'];errors=[];p.on('pageerror',lambda e:errors.append(str(e)));expect(root.locator('.insight-month-window')).to_be_attached();p.locator('[data-section=listening]').click();p.locator('#insights-screen').click();p.locator('[data-section=live]').click();p.locator('#insights-screen').click();expect(root.locator('.insight-month-window')).to_be_attached();assert not errors,errors;before=p.evaluate(SNAP)
  root.locator('.insight-settings').click();d=p.locator('.insight-layout-modal');assert d.locator('input[data-item=score]').is_checked();assert not d.locator('input[data-item=venue]').is_checked();d.get_by_role('button',name='Done',exact=True).click();assert p.evaluate(SNAP)==before
  p.reload();p.evaluate('MLAReady');p.locator('[data-section=live]').click();p.locator('#insights-screen').click();assert order(root)==['time','artists','score']
  root.locator('.insight-settings').click();d=p.locator('.insight-layout-modal');d.get_by_role('button',name='Reset to Default',exact=True).click();d.get_by_role('button',name='Done',exact=True).click();assert order(root)==['artists','score','venue','time'];assert p.evaluate(SNAP)==before
  # Photo/no photo, full-period dates including unknown, zero and 15/16 paging.
  rank=root.locator('[data-insight=score]');assert rank.locator('select').count()==0;rank.get_by_role('button',name='Show more',exact=True).click();rank.get_by_role('button',name='Show more',exact=True).click();assert '0.0/5' in rank.inner_text();assert 'Hidden artist' not in rank.inner_text();assert rank.locator('img').count()==1
  p.locator('#archive-screen').click();p.locator('#library .coverbtn').filter(has_text='Festival with photo').click();p.locator('#view-edit').click();slider=p.locator('[data-target=e-live-rating] .star-rating');slider.focus();p.keyboard.press('Home');p.locator('#save').click();expect(p.locator('#modal')).not_to_be_visible();p.locator('#insights-screen').click();expect(rank.locator('li').filter(has_text='Festival with photo').locator('.rating-number')).to_have_text('0.0/5')
  p.locator('#archive-screen').click();p.locator('#library .coverbtn').filter(has_text='Festival with photo').click();p.locator('#view-edit').click();p.locator('#delete').click();p.locator('#delete-accept').click();expect(p.locator('#modal')).not_to_be_visible();p.locator('#insights-screen').click();expect(rank).not_to_contain_text('Festival with photo')
  p.locator('#archive-screen').click();p.locator('#add-live-trigger').click();p.locator('#live-title').fill('Fresh live score');slider=p.locator('[data-target=live-rating] .star-rating');slider.focus();p.keyboard.press('End');p.locator('#live-form > button').click();expect(p.locator('#live-create-modal')).not_to_be_visible();p.locator('#insights-screen').click();expect(rank).to_contain_text('Fresh live score');expect(rank.locator('li').filter(has_text='Fresh live score').locator('.rating-number')).to_have_text('5.0/5')
  print('PASS Live score real edit to zero, delete and create refresh ranking',flush=True)
  # Blank Live titles cannot pass the existing validator; verify only the defensive display branch without saving.
  p.evaluate('''()=>MLAInsights.render(document.querySelector('#live-insights'),[{title:'',artists:['Second','First','Third'],date:'',venue:'',rating:'10'},{title:'Festival',artists:['MUST NOT APPEAR'],date:'2026-11-01',venue:'Hall',rating:'0'},{title:'Unrated',rating:''}],'live',false,new Date(2026,10,27))''');titles=rank.locator('.insight-score-title').all_text_contents();assert titles==['Second / First / Third','Festival'];assert 'MUST NOT APPEAR' not in rank.inner_text();assert rank.locator('.insight-score-date').count()==1;assert rank.locator('.insight-score-venue').count()==1;assert '0.0' in rank.inner_text()
  root.screenshot(path=str(E/'live-ranking-fallback.png'))
  print('PASS Live layout migration, reset, persistence, no IDB change; score zero/unrated/photo/no-photo; defensive ordered-artist fallback',flush=True)
  browser.close()
 (E/'history-performance.json').write_text(json.dumps(results,indent=2));server.shutdown()
if __name__=='__main__':main()
